  "probability": 0.95,
  "range_low": 0.90,
  "range_high": 0.98,
  "summary": [
    "Credible outlets confirmed Khamenei's death on Feb 28, 2026, ending his tenure as Supreme Leader.",
    "Iran's Assembly of Experts provides a defined path to appoint a new leader, enabling a rapid transition.",
    "Official state acknowledgment and mourning signaling further consolidate the transition timeline."
  ],
  "confidence": "high",
  "narrative": "The death confirmation triggers the constitutionally mandated succession process, making cessation before April 1, 2026 effectively settled. The combination of credible reporting and a formal mechanism yields a high-confidence near-term exit; remaining uncertainty centers on interim leadership formalization and timing of appointment.",
  "justification": {
    "anchor": {
      "probability": 0.60,
      "basis": "baseline reference-class probability for near-term turnover in long-tenured Iranian leadership prior to any confirmed cessation; aligns with markets pre-event odds suggesting meaningful probability of change within 2026."
    },
    "factor_updates": [
      {
        "factor": "confirmed_death_feb_28_2026",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "Multiple credible outlets reported death; this directly ends tenure and triggers succession."
      },
      {
        "factor": "assembly_of_experts_succession_mechanism",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Constitutional pathway provides rapid appointment, reducing transition uncertainty."
      },
      {
        "factor": "official_state_acknowledgment_and_mourning_period",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "State media acknowledgement formalizes transition; mourning signals structured timelines."
      },
      {
        "factor": "prediction_markets_pre_event_odds",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Markets priced non-trivial odds of exit within 2026, lending external calibration to likelihood of near-term change."
      },
      {
        "factor": "health_longevity_risk_pre_event",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "But on death confirmation, longevity concerns are superseded; prior risk in absence of death would dampen probability somewhat."
      }
    ],
    "synthesis_rationale": "The posterior integrates strong direct evidence of cessation (death), a durable constitutional mechanism for succession, and corroborating state actions, while considering pre-event market calibration. Correlation among factors is acknowledged; calibration toward 0.95 reflects high confidence in near-term cessation, with residual uncertainty mainly about interim leadership sequencing and timing."
  }
}

